<?php require_once __DIR__.'/../helpers/bootstrap.php'; layout_start('Dashboard'); $p=db()->query('SELECT COUNT(*) total, COALESCE(SUM(stock*price),0) value, SUM(stock<=minimum_stock) low FROM products')->fetch(); $m=db()->query("SELECT COALESCE(SUM(type='IN'*quantity),0) incoming, COALESCE(SUM(type='OUT'*quantity),0) outgoing FROM stock_movements")->fetch(); $low=db()->query('SELECT sku,name,stock,minimum_stock FROM products WHERE stock<=minimum_stock ORDER BY stock')->fetchAll(); ?><h1>Dashboard</h1><section class="cards"><div><b><?=e($p['total'])?></b><span>Total produk</span></div><div><b>Rp <?=number_format($p['value'],0,',','.')?></b><span>Nilai inventory</span></div><div><b><?=e($p['low'])?></b><span>Stok rendah</span></div><div><b><?=e($m['incoming'])?> / <?=e($m['outgoing'])?></b><span>Masuk / keluar</span></div></section><section class="panel"><h2>Perlu perhatian</h2><?php if(!$low):?><p>Semua stok aman.</p><?php else:?><table><tr><th>SKU</th><th>Produk</th><th>Stok</th><th>Minimum</th></tr><?php foreach($low as $x):?><tr><td><?=e($x['sku'])?></td><td><?=e($x['name'])?></td><td><?=e($x['stock'])?></td><td><?=e($x['minimum_stock'])?></td></tr><?php endforeach?></table><?php endif?></section><?php layout_end();
